import assert from 'node:assert/strict';
import {writeFileSync} from 'node:fs';
const study='/tmp/engine-fused-detection-20261106';
const a=await import(study+'/reference/scripts/lib/detector.ts'),b=await import('/home/holo/line/scripts/lib/detector.ts');
let seed=0x199fc388,comparisons=0;const random=()=>((seed=(Math.imul(seed,1664525)+1013904223)>>>0)/2**32);
function trajectory(length:number){return Array.from({length},(_,frame)=>({frame,position:{x:random()<.005?1e7:frame,y:random()*5},velocity:{x:random()<.1?0:random()*5,y:random()<.1?0:random()*4-2},sledContacts:random()<.35?['PEG']:[],contactLineIds:random()<.35?[1000]:[],sledBroken:random()<.005,riderEjected:random()<.005}));}
function capture(fn:()=>unknown){try{return {value:structuredClone(fn())}}catch(e){return {error:String(e)}}}
for(let trial=0;trial<1000;trial++){
 const frames=trajectory(120);
 if(trial%3===0){const values=[0,-0,Number.MIN_VALUE,-Number.MIN_VALUE,Infinity,-Infinity,NaN,1e308,1e-308];for(let i=0;i<frames.length;i++){frames[i].velocity.x=values[i%values.length];frames[i].velocity.y=values[(i+trial)%values.length];}}
 const prefix=frames.slice(0,trial%45),params={persistenceFrames:[1,2,5,8][trial%4],vStallFrames:[1,3,20][trial%3],persistenceRatio:[0,.5,1][trial%3]};
 const old=new a.DetectionContinuation({duration:prefix.length-1,frames:prefix},params),next=new b.DetectionContinuation({duration:prefix.length-1,frames:prefix},params);
 for(const suffix of [frames,trajectory(160),frames])for(const length of [160,120,50,prefix.length+1,prefix.length,0]){
  const raw={duration:length-1,frames:prefix.concat(suffix.slice(prefix.length,length)).slice(0,length)};
  assert.deepEqual(capture(()=>b.detect(raw,params)),capture(()=>a.detect(raw,params)));comparisons++;
  assert.deepEqual(capture(()=>next.withDetection(raw,d=>d)),capture(()=>old.withDetection(raw,d=>d)));comparisons++;
  if(trial%10===0){assert.deepEqual(capture(()=>next.withDetection(raw,()=>{throw Error('test')})),capture(()=>old.withDetection(raw,()=>{throw Error('test')})));comparisons++;}
 }
}
writeFileSync(study+'/comparison.json',JSON.stringify({status:'PASS',comparisons},null,2)+'\n');console.log({comparisons});
